import hashlib,json,os,shutil,statistics,subprocess,time
from pathlib import Path
os.sched_setaffinity(0,{0})
work=Path('build/review-j20-performance').resolve();work.mkdir(exist_ok=True)
frozen=Path('build/review-j12-performance-inputs').resolve()
target=Path('docs/review-performance/J20.json')
data={'parent_commit':'923d6e9','parent_code_commit':'142e203','protocol':'CPU0, seed7, 3 alternating pairs; 5 confirmation pairs if median time +20% or RSS +25%. No concurrent own builds/tests. Historical parent has root objects without LTO but reused C-CFR O3 LTO archive. Candidate is fully O3 without LTO. A clean build from the parent Makefile under the same effective options produces all three candidate executables byte for byte. This run measures the transition from the historical mixed build, not an algorithm change.', 'runs':[],'summary':[],'blocked':None}
def digest(path):
 with open(path,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def save():
 data['script']=Path(__file__).read_text();data['launcher_source']=Path('/tmp/mus-review-j12-measure.c').read_text()
 target.write_text(json.dumps(data,indent=2)+'\n')
def execute(command):
 rss=work/'rss.txt';full=['/tmp/mus-review-j12-measure',str(rss),*map(str,command)]
 start=time.perf_counter();p=subprocess.run(full,capture_output=True,text=True);elapsed=time.perf_counter()-start
 assert p.returncode==0,(full,p.returncode,p.stderr)
 return p.stdout,elapsed,int(rss.read_text())
data['binary_hashes']={str(p):digest(p) for directory in ('review-j18','review-j20','review-j20-parent-clean') for name in ('mus-solver','mus-bot','mus-match-eval') for p in [Path('build')/directory/'release'/name]}
for variant in ('ordago','ordago-public'):
 p=frozen/f'{variant}.txt';data.setdefault('inputs',{})[str(p)]={'bytes':p.stat().st_size,'sha256':digest(p)}
for group in ('train-public','train-score','legacy-txt','public-txt'):
 reference=None
 def pair(repeat):
  global reference
  for version in (('parent','candidate') if repeat%2 else ('candidate','parent')):
   binary=Path('build/review-j18/release' if version=='parent' else 'build/review-j20/release').resolve()
   if group=='train-public':
    output=work/f'{version}-{repeat}.cfr';command=[binary/'mus-solver','--format','ordago-public','--iterations','500','--seed','7','--save',output]
   elif group=='train-score':
    output=work/f'table-{version}-{repeat}';command=[binary/'mus-solver','--format','ordago-score','--score','35:35','--iterations','1000','--evaluation-samples','10000','--seed','7','--continuation',output]
   else:
    variant='ordago' if group=='legacy-txt' else 'ordago-public';command=[binary/'mus-match-eval','--strategy-a',frozen/f'{variant}.txt','--opponent','three','--score','0:0','--matches','1000' if variant=='ordago' else '10000','--seed','7']
   out,wall,rss=execute(command)
   row={'group':group,'version':version,'repeat':repeat,'command':list(map(str,command)),'wall_seconds':wall,'peak_rss_kib':rss}
   if group=='train-public':h=digest(output);output.unlink();row['stdout']=out
   elif group=='train-score':
    h={p.name:digest(p) for p in output.iterdir() if p.name=='values.txt' or p.name.endswith('.cfr.zst')};shutil.rmtree(output);row['stdout']=out
   else:
    result=json.loads(out);row['game_seconds']=result.pop('seconds');h=hashlib.sha256(json.dumps(result,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    row.update({k:result[k] for k in ('matches','wins','hands','decisions','checksum')})
   if reference is None:reference=h
   assert h==reference,(group,version)
   row['identical_results_sha256']=h;data['runs'].append(row);save();print(group,version,repeat,round(wall,4),rss,flush=True)
 def summary(confirm=False):
  rows=[r for r in data['runs'] if r['group']==group and (r['repeat']>3)==confirm];s={'group':group,'confirmation':confirm}
  for field in ['wall_seconds','peak_rss_kib']+(['game_seconds'] if 'game_seconds' in rows[0] else []):
   a=statistics.median(r[field] for r in rows if r['version']=='parent');b=statistics.median(r[field] for r in rows if r['version']=='candidate');s[field]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
  s['trigger']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
  data['summary'].append(s);save();print(s,flush=True);return s['trigger']
 for repeat in range(1,4):pair(repeat)
 if summary():
  for repeat in range(4,9):pair(repeat)
  if summary(True):data['blocked']=group;save();raise SystemExit(2)
save()

