#define _GNU_SOURCE
#include <spawn.h>
#include <stdio.h>
#include <sys/wait.h>
#include <sys/resource.h>
#include <errno.h>
extern char **environ;
int main(int argc, char **argv) {
    if (argc < 3) return 2;
    pid_t pid;
    if (posix_spawn(&pid, argv[2], NULL, NULL, argv + 2, environ) != 0) return 3;
    int status; struct rusage usage;
    while (wait4(pid, &status, 0, &usage) < 0) if (errno != EINTR) return 4;
    FILE *output = fopen(argv[1], "w");
    if (!output) return 5;
    if (fprintf(output, "%ld\n", usage.ru_maxrss) < 0 || fclose(output)) return 6;
    return WIFEXITED(status) ? WEXITSTATUS(status) : 128 + WTERMSIG(status);
}
